import json
d=json.load(open('$f'))
print('=== interaction_index ===')
ii = d.get('interaction_index', {})
if isinstance(ii, dict):
    for k, v in ii.items():
        print(f'  {k}: {v}')
print('=== pass_fail ===')
pf = d.get('pass_fail', {})
if isinstance(pf, dict):
    for k, v in pf.items():
        print(f'  {k}: {v}')
