ps = d.get('phase_stats', {})
if isinstance(ps, dict):
    for k, v in ps.items():
        print(f'  {k}: {v}')
print('=== perplexity ===')
pp = d.get('perplexity', {})
if isinstance(pp, dict):
    for k, v in pp.items():
        print(f'  {k}: {v}')
print('=== config ===')
